ALUSUS {
  global:
    get_library_gateway;
    # The GDB JIT interface, which is how debuggers learn about code generated by the JIT. Debuggers look these
    # symbols up by name. With them hidden, like the rest of the LLVM symbols, gdb did not pick up JIT generated code,
    # so we export them.
    __jit_debug_register_code;
    __jit_debug_descriptor;

  local:
    *;
};
